{"path": "/workspace/target/src/text_views.py", "content": """"Text normalization and document assembly for the deployed candidate.

Serving boundary is pre-outcome: only the pre-outcome narrative fields
(title + case_summary) are eligible index text.  Post-adjudication fields
(final_diagnosis), display/bibliographic metadata (journal) and derived
counters (domain_hits) are not release-eligible and are excluded.
"""
from __future__ import annotations

import re
import unicodedata
from typing import Any

ELIGIBLE_FIELDS = ("title", "case_summary")


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", str(text)).lower()
    return re.sub(r"\s+", " ", text).strip()


def document_text(row: dict[str, Any]) -> str:
    return normalize(" ".join(str(row.get(field, "") or "") for field in ELIGIBLE_FIELDS))


def query_text(text: str) -> str:
    return normalize(text)
"}

{"path": "/workspace/target/src/ranker.py", "content": """"Ranking implementation for the deployed candidate.

Release behavior (established from the gated operational receipts):

  * Population: manifest-active files only, joined to the identity registry
    on the stable ``record_key``; the canonical output identity is the
    registry ``pmcid``.
  * Eligible text: pre-outcome narrative only (title + case_summary).
  * Lexical index: built *within each cause family* (domain), two views
      view_a: word 1-2 grams, min_df=2, max_df=0.98
      view_b: char_wb 3-5 grams, min_df=2
    Each view is scored against that family's own request facet.
  * Fusion: raw similarity scales are not exchangeable across views, so the
    accepted release value is reciprocal-rank fusion over the two
    within-family rank positions with k=60.
  * Allocation: request-sized, balanced across the three active families.
"""
from __future__ import annotations

from collections import Counter
from typing import Any

import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import linear_kernel

from .text_views import document_text, normalize

RRF_K = 60
FAMILIES = ("cardiac", "vascular", "systemic")

VIEW_CONFIGS = (
    dict(analyzer="word", ngram_range=(1, 2), min_df=2, max_df=0.98, strip_accents="unicode"),
    dict(analyzer="char_wb", ngram_range=(3, 5), min_df=2, strip_accents="unicode"),
)


def _view_ranks(documents: list[str], query: str, pmcids: np.ndarray, config: dict[str, Any]) -> np.ndarray:
    n = len(documents)
    if n == 0:
        return np.zeros(0, dtype=int)
    try:
        vectorizer = TfidfVectorizer(**config)
        matrix = vectorizer.fit_transform(documents)
        scores = linear_kernel(vectorizer.transform([query]), matrix).ravel()
    except ValueError:
        scores = np.zeros(n)
    order = np.lexsort((pmcids, -scores))
    ranks = np.empty(n, dtype=int)
    ranks[order] = np.arange(1, n + 1)
    return ranks


def _facet_for(family: str, facets: dict[str, Any]) -> str:
    for key, value in facets.items():
        if str(key).strip().lower() == family:
            return normalize(str(value))
    return normalize(" ".join(str(v) for v in facets.values()))


def _family_ranking(rows: list[dict[str, Any]], facets: dict[str, Any]) -> list[dict[str, Any]]:
    """Fused, ordered candidate list for one cause family."""
    if not rows:
        return []
    family = str(rows[0]["source"])
    documents = [document_text(row) for row in rows]
    pmcids = np.array([str(row["pmcid"]) for row in rows])
    query = _facet_for(family, facets)
    rank_views = [_view_ranks(documents, query, pmcids, dict(cfg)) for cfg in VIEW_CONFIGS]
    fused = np.zeros(len(rows))
    for ranks in rank_views:
        fused = fused + 1.0 / (RRF_K + ranks)
    order = np.lexsort((pmcids, -fused))
    return [
        {
            "pmcid": str(rows[i]["pmcid"]),
            "source": family,
            "score": round(float(fused[i]), 12),
        }
        for i in order
    ]


def allocate(per_family: dict[str, list[dict[str, Any]]], top_k: int, request: dict[str, Any]) -> list[dict[str, Any]]:
    """Request-sized balanced allocation across the active cause families."""
    cycle = family_cycle(request, per_family)
    cursors = {family: 0 for family in per_family}
    panel: list[dict[str, Any]] = []
    guard = 0
    while len(panel) < top_k and guard < top_k * 8:
        progressed = False
        for family in cycle:
            if len(panel) >= top_k:
                break
            pool = per_family.get(family, [])
            index = cursors.get(family, 0)
            if index < len(pool):
                panel.append(pool[index])
                cursors[family] = index + 1
                progressed = True
        guard += 1
        if not progressed:
            break
    return panel


def family_cycle(request: dict[str, Any], per_family: dict[str, list[dict[str, Any]]]) -> list[str]:
    """Deterministic family emission order (request-phase); overridden by evidence."""
    present = [f for f in FAMILIES if per_family.get(f)]
    if not present:
        return []
    return present


def rank_cases(rows: list[dict[str, Any]], request: dict[str, Any]) -> dict[str, Any]:
    facets = request.get("facets", {}) or {}
    try:
        top_k = int(request.get("top_k", 12))
    except (TypeError, ValueError):
        top_k = 12
    if top_k < 0:
        top_k = 0
    top_k = min(top_k, len(rows))

    grouped: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        grouped.setdefault(str(row["source"]), []).append(row)

    per_family = {family: _family_ranking(items, facets) for family, items in grouped.items()}
    results = allocate(per_family, top_k, request)

    domain_counts = Counter(str(r["source"]) for r in rows)
    return {
        "corpus_count": len(rows),
        "domain_counts": dict(sorted(domain_counts.items())),
        "results": results,
        "pmcids": [r["pmcid"] for r in results],
        "method": "family_balanced_dual_view_rrf",
    }
"}

